package main

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
)

var data []byte
var pos int

// nextNumber returns the next run of decimal digits with leading zeros stripped
// (labels may exceed 64 bits).
func nextNumber() string {
	for pos < len(data) && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		pos++
	}
	first := start
	for first+1 < pos && data[first] == '0' {
		first++
	}
	return string(data[first:pos])
}

var labels = map[string]int{}
var parent, size []int

func indexOf(label string) int {
	if id, ok := labels[label]; ok {
		return id
	}
	id := len(parent)
	labels[label] = id
	parent = append(parent, id)
	size = append(size, 1)
	return id
}

func find(x int) int {
	for parent[x] != x {
		parent[x] = parent[parent[x]]
		x = parent[x]
	}
	return x
}

type edge struct{ w, u, v int }

func main() {
	data, _ = io.ReadAll(os.Stdin)
	nextNumber() // N is not needed: only labels that appear are stored
	m, _ := strconv.Atoi(nextNumber())
	edges := make([]edge, m)
	for i := range edges {
		u := indexOf(nextNumber())
		v := indexOf(nextNumber())
		w, _ := strconv.Atoi(nextNumber())
		edges[i] = edge{w, u, v}
	}
	source, destination := indexOf(nextNumber()), indexOf(nextNumber())
	if source == destination {
		fmt.Println(0)
		return
	}
	sort.Slice(edges, func(i, j int) bool { return edges[i].w < edges[j].w })
	for _, e := range edges {
		a, b := find(e.u), find(e.v)
		if a != b {
			if size[a] < size[b] {
				a, b = b, a
			}
			parent[b] = a
			size[a] += size[b]
		}
		if find(source) == find(destination) {
			fmt.Println(e.w)
			return
		}
	}
	fmt.Println(-1)
}
